    return CLOCK_GetOutClkFreq() / (SIM_CLKDIV1_OUTDIV1_VAL + 1U);
}

CLOCK_GetCoreSysClkFreq.function_content:
/*!
* brief Get the core clock or system clock frequency.
*
* return Clock frequency in Hz.
*/
