     * (instance >= ARRAY_SIZE(s_gpioBases)) not covered.
     * $ref gpio_c_ref_1$.
     */
    for (instance = 0; instance < ARRAY_SIZE(s_gpioBases); instance++) /* GCOVR_EXCL_BR_LINE */
